IF USER_ID(N'paws-calendar-test-runtime') IS NULL THROW 55690,'Disposable SQL required.',1;
ALTER ROLE paws_runtime_read ADD MEMBER [paws-calendar-test-runtime];
DECLARE @Batch uniqueidentifier=NEWID(),@Book uniqueidentifier=NEWID(),@Sheet uniqueidentifier=NEWID(),@Row uniqueidentifier=NEWID(),@Faculty uniqueidentifier='11111111-1111-4111-8111-111111111111',@Other uniqueidentifier='22222222-2222-4222-8222-222222222222';
INSERT staging.ImportBatch(ImportBatchId,StartedAtUtc,Status,SourceManifestSha256,ImporterVersion,ValidationSummaryJson) VALUES(@Batch,SYSUTCDATETIME(),N'completed',REPLICATE('A',64),N'availability-test',N'{}');
INSERT staging.ImportWorkbook(ImportWorkbookId,ImportBatchId,FileName,FileSha256,FileByteLength) VALUES(@Book,@Batch,N'synthetic.xlsx',REPLICATE('A',64),1);
INSERT staging.ImportSheet(ImportSheetId,ImportWorkbookId,SheetName,SheetIndex,MaxRow,MaxColumn,NonEmptyRowCount) VALUES(@Sheet,@Book,N'Synthetic',1,2,1,1);
INSERT staging.ImportRow(ImportRowId,ImportSheetId,SourceRowNumber,RawJson,ValidationStatus,ValidationErrorsJson) VALUES(@Row,@Sheet,2,N'{}',N'accepted',N'[]');
INSERT paws.Faculty(FacultyId,RecordType,DisplayName,Active,SourceImportBatchId) VALUES(@Faculty,N'faculty',N'Duplicate Example',1,@Batch),(@Other,N'faculty',N'Duplicate Example',1,@Batch);
UPDATE paws.Faculty SET DisplayName=N'Legacy Source Name',PreferredFirstName=N'Alex',PreferredLastName=N'Different',Active=0 WHERE FacultyId=@Other;
INSERT paws.UserProfile(FirebaseUid,Email,DisplayName,BaseRole,FacultyId,Active,MustChangePassword) VALUES(N'availability-admin',N'admin@example.test',N'Example Admin',N'owner',NULL,1,0),(N'availability-self',N'self@example.test',N'Example Self',N'faculty',@Faculty,1,0),(N'availability-inactive',N'inactive@example.test',N'Example Inactive',N'faculty',@Faculty,0,0),(N'availability-hicc',N'hicc@example.test',N'Example HICC',N'hicc',@Faculty,1,0),(N'availability-unsupported',N'other@example.test',N'Example Other',N'other_office',NULL,1,0);
DECLARE @Today date=CONVERT(date,SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE 'Mountain Standard Time');
DECLARE @Sessions TABLE(Id uniqueidentifier,Day date,Topic nvarchar(100),StartTime time,EndTime time);
;WITH n AS(SELECT TOP(60) ROW_NUMBER() OVER(ORDER BY object_id) n FROM sys.all_objects) INSERT @Sessions SELECT NEWID(),DATEADD(day,n,@Today),CONCAT(N'Future ',n),'09:00','10:00' FROM n;
INSERT @Sessions VALUES(NEWID(),'2024-06-01',N'Historic','09:00','10:00'),(NEWID(),@Today,N'Completed today','00:00','00:01'),(NEWID(),@Today,N'Unknown clock',NULL,NULL),(NEWID(),NULL,N'Unknown date','09:00','10:00');
INSERT paws.Session(SessionId,AcademicYear,CourseCode,SessionType,SessionDate,StartTime,EndTime,Topic,SourceImportBatchId) SELECT Id,CASE WHEN Day<'2025-01-01' THEN N'2024-25' ELSE N'2026-27' END,N'AVAIL',N'LEC',Day,StartTime,EndTime,Topic,@Batch FROM @Sessions;
INSERT paws.SessionAssignment(SessionAssignmentId,SessionId,FacultyId,FacultyResolutionStatus,SourceImportBatchId,SourceRow) SELECT NEWID(),Id,@Faculty,N'resolved',@Batch,2 FROM @Sessions;
INSERT paws.SessionAssignment(SessionAssignmentId,SessionId,FacultyId,FacultyResolutionStatus,SourceImportBatchId,SourceRow) SELECT TOP(1) NEWID(),Id,@Faculty,N'resolved',@Batch,3 FROM @Sessions;
INSERT paws.AfcRecord(AfcRecordId,FacultyId,StartDate,EndDate,Purpose,Active,SourceImportBatchId,SourceRow) VALUES(NEWID(),@Faculty,'2024-05-01','2024-06-30',N'PRIVATE MEDICAL REASON',1,@Batch,2),(NEWID(),@Faculty,@Today,@Today,N'PRIVATE CURRENT REASON',1,@Batch,3),(NEWID(),@Faculty,'2024-01-01','2024-01-02',N'Cancelled',0,@Batch,4);
INSERT paws.AfcRequest(AfcRequestId,FacultyId,FacultyName,RequesterFirebaseUid,RequesterEmail,Status,StartDate,EndDate,WorkDays,Reason,ContactAddress,ContactPhone,TermsAccepted,TermsVersion,TermsSource,TermsAcceptedAtUtc,ApplicantSignatureMode,ApplicantSignatureName,ApplicantSignatureUid,ApplicantSignatureSignedAtUtc,ApplicantSignatureFingerprint)
SELECT NEWID(),@Faculty,N'Example',N'availability-self',N'private@example.test',s.Status,@Today,@Today,1,N'vacation',N'PRIVATE ADDRESS',N'PRIVATE PHONE',1,N'test',N'test',SYSUTCDATETIME(),N'typed',N'Example',N'availability-self',SYSUTCDATETIME(),REPLICATE('A',64) FROM (VALUES(N'approved'),(N'pending_admin'),(N'rejected'),(N'withdrawn'))s(Status);
